#include <iostream>
#include <memory>
#include <utility>
struct Trace {
    int value{};
    explicit Trace(int n) : value(n) { std::cout << "create " << value << '\n'; }
    ~Trace() { std::cout << "destroy " << value << '\n'; }
};
int main() {
    auto owner = std::make_unique<Trace>(5);
    Trace* observer = owner.get();
    auto next = std::move(owner);
    std::cout << (!owner) << ' ' << (observer == next.get()) << '\n';
    next.reset();
}

